COST_PER_1K = {"fast-small": 1, "balanced": 3, "frontier": 15}

REQUESTS = [
    {"id": "r1", "tokens": 1000, "complexity": "low"},
    {"id": "r2", "tokens": 2000, "complexity": "medium"},
    {"id": "r3", "tokens": 8000, "complexity": "low"},
    {"id": "r4", "tokens": 1000, "complexity": "high"},
]

def route(req):
    if req['tokens'] > 4000 or req['complexity'] == 'high':
        return 'frontier'
    elif req['complexity'] == 'medium':
        return 'balanced'
    else:
        return 'fast-small'

def cost_units(req, model):
    return (req['tokens'] // 1000) * COST_PER_1K[model]

total = 0
for req in REQUESTS:
    model = route(req)
    cost = cost_units(req, model)
    total += cost
    print(f"{req['id']} -> {model} (cost={cost})")
print(f"Total cost units: {total}")
